# Surah Yusuf (chapter 12) — part 1: ayat 1-10 (IDs 1597-1606)
SURAH = 12

ENTRIES = {
1597: (
"بسم اللہ الرحمٰن الرحیم — الر — یہ — واضح کتاب کی آیات ہیں",
"""۱۔ سورہ یوسف — واضح کتاب — کی آیات۔
۲۔ ’’الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ‘‘ — الر — یہ — واضح کتاب کی آیات ہیں — یعنی یہ آیات — واضح کتاب — کی ہیں۔
۳۔ عملی سبق: قرآن — واضح ہے؛ سمجھ کر پڑھیں۔"""
),
1598: (
"بے شک — ہم — نے — اس — کو — عربی قرآن — بنا کر نازل کیا — تاکہ — تم — سمجھو",
"""۱۔ قرآن — عربی میں — سمجھنے کے لیے — نازل ہوا۔
۲۔ ’’إِنَّا أَنزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ‘‘ — بے شک — ہم — نے — اس — کو — عربی قرآن — بنا کر نازل کیا — تاکہ — تم — سمجھو — یعنی ہم نے — اسے — عربی قرآن بنا کر — نازل کیا — تاکہ — تم — سمجھو۔
۳۔ عملی سبق: قرآن — عربی میں سمجھے — جانے کے لیے — ہے؛ تدبر کرو۔"""
),
1599: (
"ہم — آپؐ — پر — بہترین قصص — سناتے ہیں — اس — وحی کے ذریعے — جو — ہم — نے — آپؐ کی طرف — کی — اور — آپؐ — اس — سے پہلے — یقیناً — غافلوں — میں — سے تھے",
"""۱۔ قرآن — بہترین قصص — پر مشتمل — وحی — ہے۔
۲۔ ’’نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِن كُنتَ مِن قَبْلِهِ لَمِنَ الْغَافِلِينَ‘‘ — ہم — آپؐ — پر — بہترین قصص — سناتے ہیں — اس — وحی کے ذریعے — جو — ہم — نے — آپؐ کی طرف — کی — اور — آپؐ — اس — سے پہلے — یقیناً — غافلوں — میں — سے تھے — یعنی ہم — آپؐ کو — بہترین قصص — سناتے ہیں — اس وحی — کے ذریعے جو — آپؐ کی طرف کی گئی — یہ قرآن ہے — اور — آپؐ — اس سے پہلے — غافلوں میں سے تھے۔
۳۔ عملی سبق: قرآن — بہترین نصیحتوں — سے بھرا ہے؛ غور سے پڑھیں۔"""
),
1600: (
"جب — یوسف — نے — اپنے باپ — سے — کہا — اے میرے ابا — میں نے — گیارہ ستارے — سورج اور چاند — دیکھے — میں نے — دیکھا — ان — کو — میرے — سامنے — سجدہ — کر رہے ہیں",
"""۱۔ یوسفؑ — کا خواب — گیارہ ستارے، سورج اور چاند — سجدے میں۔
۲۔ ’’إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ‘‘ — جب — یوسف — نے — اپنے باپ — سے — کہا — اے میرے ابا — میں نے — گیارہ ستارے — سورج اور چاند — دیکھے — میں نے — دیکھا — ان — کو — میرے — سامنے — سجدہ — کر رہے ہیں — یعنی یوسفؑ — نے کہا — اے میرے ابا — میں نے — گیارہ ستارے — سورج اور چاند — دیکھے — ان کو — میرے سامنے سجدہ کرتے — ہوئے دیکھا۔
۳۔ عملی سبق: خواب — بھی اللہ کی نشانی — ہو سکتے ہیں؛ صحیح تعبیر — علم — ہے۔"""
),
1601: (
"انہوں نے — کہا — اے میرے بیٹے — اپنا — یہ خواب — اپنے — بھائیوں — سے — بیان — نہ — کرو — کہ وہ — تمہارے — لیے — چال — چلیں گے — بے شک — شیطان — انسان — کا — کھلا دشمن — ہے",
"""۱۔ یعقوبؑ — خواب — چھپانے کی نصیحت — بھائیوں کے حسد — سے خبردار۔
۲۔ ’’قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنسَانِ عَدُوٌّ مُّبِينٌ‘‘ — انہوں نے — کہا — اے میرے بیٹے — اپنا — یہ خواب — اپنے — بھائیوں — سے — بیان — نہ — کرو — کہ وہ — تمہارے — لیے — چال — چلیں گے — بے شک — شیطان — انسان — کا — کھلا دشمن — ہے — یعنی یعقوبؑ — نے کہا — اے میرے بیٹے — اپنا — خواب — اپنے — بھائیوں — سے — بیان — نہ کرو — کہ وہ تمہارے لیے — چال — چلیں گے — بے شک — شیطان — انسان — کا — کھلا دشمن — ہے۔
۳۔ عملی سبق: نعمت — چھپا کر رکھنا — بعض اوقات — ضروری ہے؛ حسد — سے بچیں۔"""
),
1602: (
"اور — اسی طرح — تمہارا رب — تمہیں — چنے گا — اور — تم — کو — حدیثوں کی تاویل — سکھائے گا — اور — تم — پر — اپنی — نعمت — پوری — کرے گا — اور — یعقوبؑ — کے — خاندان — پر — اسی — طرح — جیسے — اس — نے — اس سے پہلے — تمہارے دونوں باپ دادا — ابراہیم اور اسحاقؑ — پر — پوری — کی — بے شک — تمہارا رب — علم — والا حکمت — والا ہے",
"""۱۔ یعقوبؑ — یوسفؑ — کی — بشارت: چنّہ جانا، تاویل سکھانا — اور — نعمت — کی تکمیل۔
۲۔ ’’وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِن قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ‘‘ — اور — اسی طرح — تمہارا رب — تمہیں — چنے گا — اور — تم — کو — حدیثوں کی تاویل — سکھائے گا — اور — تم — پر — اپنی — نعمت — پوری — کرے گا — اور — یعقوبؑ — کے — خاندان — پر — اسی — طرح — جیسے — اس — نے — اس سے پہلے — تمہارے دونوں باپ دادا — ابراہیم اور اسحاقؑ — پر — پوری — کی — بے شک — تمہارا رب — علم — والا حکمت — والا ہے — یعنی یعقوبؑ — نے کہا — تمہارا رب — تمہیں چنّے گا — اور — تمہیں — خوابوں — کی تعبیر — سکھائے گا — اور — تم — پر — اپنی نعمت — پوری — کرے گا — تم — پر اور یعقوبؑ کے خاندان — پر — جیسے — اس — نے — پہلے ابراہیم اور اسحاقؑ — پر — پوری — کی — بے شک تمہارا رب — علیم و حکیم ہے۔
۳۔ عملی سبق: اللہ کی نعمت — چناؤ — اور — علم — کی صورت — میں — ملتی ہے۔"""
),
1603: (
"بے شک — یوسفؑ — اور — اس — کے بھائیوں — میں — سوال کرنے والوں — کے لیے — نشانیاں — ہیں",
"""۱۔ یوسفؑ کا واقعہ — عبرت — کے لیے نشانیاں۔
۲۔ ’’لَّقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِّلسَّائِلِينَ‘‘ — بے شک — یوسفؑ — اور — اس — کے بھائیوں — میں — سوال کرنے والوں — کے لیے — نشانیاں — ہیں — یعنی یوسفؑ — اور اس کے بھائیوں — میں — پوچھنے والوں — کے لیے — نشانیاں — ہیں۔
۳۔ عملی سبق: قرآن کی کہانیاں — سوال — کرنے والوں کے لیے — جواب ہیں۔"""
),
1604: (
"جب — انہوں نے — کہا — یوسفؑ — اور — اس کا بھائی — ہمارے باپ — کو — ہم — سے — زیادہ — پیارے — ہیں — اور — ہم — ایک — جماعت — ہیں — بے شک — ہمارا باپ — واضح گمراہی — میں ہے",
"""۱۔ بھائی — یوسفؑ اور بینیامین — کی طرف — باپ کی محبت پر جلتے ہیں۔
۲۔ ’’إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَۃٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُّبِينٍ‘‘ — جب — انہوں نے — کہا — یوسفؑ — اور — اس کا بھائی — ہمارے باپ — کو — ہم — سے — زیادہ — پیارے — ہیں — اور — ہم — ایک — جماعت — ہیں — بے شک — ہمارا باپ — واضح گمراہی — میں ہے — یعنی جب — انہوں نے کہا — یوسفؑ — اور اس کا بھائی — ہمارے — باپ — کو — ہم — سے زیادہ — پیارے ہیں — اور — ہم — ایک — طاقت — ور — جماعت — ہیں — بے شک — ہمارا باپ — واضح گمراہی — میں ہے۔
۳۔ عملی سبق: حسد — برداشت — نہ کیا جائے؛ رشتے — خون — سے — بڑھ — کر ہوتے ہیں۔"""
),
1605: (
"یوسفؑ — کو قتل کرو — یا — اسے — زمین — میں پھینک دو — تمہارے — باپ کی توجہ — تمہارے لیے — خالص — ہو جائے گی — اور — اس کے بعد — تم — نیکوکار — ہو — جاؤ گے",
"""۱۔ بھائی — یوسفؑ — کو — راستے سے ہٹانے کی سازش۔
۲۔ ’’اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِن بَعْدِهِ قَوْمًا صَالِحِينَ‘‘ — یوسفؑ — کو قتل کرو — یا — اسے — زمین — میں پھینک دو — تمہارے — باپ کی توجہ — تمہارے لیے — خالص — ہو جائے گی — اور — اس کے بعد — تم — نیکوکار — ہو — جاؤ گے — یعنی یوسف کو — قتل کرو — یا — اسے زمین — میں پھینک دو — تمہارے — باپ — کی توجہ — تمہارے لیے — خالص — ہو جائے گی — اور — اس — کے بعد — تم — نیکوکار — ہو — جاؤ گے (ظالمانہ — خود فریبی)۔
۳۔ عملی سبق: گناہ — کو — نیکی — کا — نام دینا — خود فریبی — ہے۔"""
),
1606: (
"ان — میں سے — ایک — کہنے والے نے کہا — یوسفؑ — کو — قتل نہ کرو — اور — اس — کو — کنویں — کی اندھیری — جگہ — میں ڈال دو — کچھ مسافر — اسے — اٹھا لے جائیں گے — اگر — تم — کرنے — والے — ہو",
"""۱۔ ایک بھائی — قتل کے بجائے — کوئیں میں ڈالنے کی تجویز۔
۲۔ ’’قَالَ قَائِلٌ مِّنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَۃِ إِن كُنتُمْ فَاعِلِينَ‘‘ — ان — میں سے — ایک — کہنے والے نے کہا — یوسفؑ — کو — قتل نہ کرو — اور — اس — کو — کنویں — کی اندھیری — جگہ — میں ڈال دو — کچھ مسافر — اسے — اٹھا لے جائیں گے — اگر — تم — کرنے — والے — ہو — یعنی ان — میں سے ایک نے کہا — یوسف کو قتل نہ کرو — اسے کنویں — کی اندھیری جگہ — میں — ڈال دو — کوئی — مسافر — اسے — اٹھا لے جائے گا — اگر — تم — کرنے — والے — ہو۔
۳۔ عملی سبق: شر میں — بھی — ایک بھلائی کا عنصر — ہو سکتا ہے؛ اللہ — سب — جانتا ہے۔"""
),
}
